<?php require 'config.php'; require_role('Admin','Faculty','Student'); $u=me(); $id=(int)($_GET['id']??0);
$d=doc_load($id); if(!$d||!can_view($d)) forbid('Document not found, or you are not authorized to open it.');
$p=perms($d,$u); $title=$d['document_id'];
$vers=q("SELECT v.*,u.full_name FROM document_versions v JOIN users u ON u.id=v.uploaded_by WHERE v.document_id=? ORDER BY v.id DESC",[$id])->fetchAll();
$revs=q("SELECT r.*,u.full_name FROM document_reviews r JOIN users u ON u.id=r.reviewer_id WHERE r.document_id=? ORDER BY r.id DESC",[$id])->fetchAll();
$hist=q("SELECT a.*,u.full_name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.document_id=? ORDER BY a.id DESC LIMIT 50",[$id])->fetchAll();
$shares=($u['role']==='Admin'||$d['uploaded_by']==$u['id'])?q("SELECT s.*,x.full_name,x.role,b.full_name AS by_name FROM document_shares s JOIN users x ON x.id=s.shared_with JOIN users b ON b.id=s.shared_by WHERE s.document_id=?",[$id])->fetchAll():[];
$targets=$p['share']?q("SELECT id,full_name,role FROM users WHERE status='Active' AND role IN ('Admin','Faculty','Student') AND id<>? ORDER BY full_name",[$u['id']])->fetchAll():[];
$st=$d['status']; $steps=['Received/Created','Uploaded','Organized','Review','Stored','Search/Use/Share','Archived'];
$cur=['Draft'=>2,'Pending Review'=>3,'Returned for Revision'=>3,'Rejected'=>3,'Approved'=>5,'Archived'=>6][$st];
$link=(isset($_SERVER['HTTPS'])?'https':'http').'://'.$_SERVER['HTTP_HOST'].rtrim(dirname($_SERVER['SCRIPT_NAME']),'/').'/document_view.php?id='.$id;
$viewable=in_array($d['file_type'],['pdf','jpg','jpeg','png','txt'],true);
include 'includes/header.php'; ?>
<div class="d-flex flex-wrap justify-content-between align-items-start mb-3 gap-2"><div><h1 class="page-title mb-1"><?=e($d['title'])?></h1><span class="text-muted"><?=e($d['document_id'])?></span> <?=badge($st)?> <span class="badge bg-light text-dark border">v<?=e($d['current_version'])?></span><?php if(!empty($d['is_late']) || ($d['submission_timing'] ?? '') === 'Delayed / Late Submitted'): ?> <span class="badge bg-danger text-white"><i class="bi bi-clock-history"></i> Delayed / Late Submitted</span><?php endif; ?></div>
 <div class="d-flex flex-wrap gap-2">
 <?php if($viewable) echo '<a class="btn btn-outline-primary" target="_blank" href="download.php?id='.$id.'&inline=1"><i class="bi bi-eye"></i> View</a>'; ?>
 <a class="btn btn-primary" href="download.php?id=<?=$id?>"><i class="bi bi-download"></i> Download</a>
 <?php if($p['edit']) echo '<a class="btn btn-outline-secondary" href="document_form.php?id='.$id.'"><i class="bi bi-pencil"></i> Edit</a>';
  if($p['submit']) echo post_btn('submit',$id,'<i class="bi bi-send"></i> Submit for Review','btn-warning','Submit this document for review? You will not be able to edit it while it is pending.');
  if($p['share']) echo '<button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#shareM"><i class="bi bi-share"></i> Share</button><button class="btn btn-outline-primary js-copy" data-url="'.e($link).'"><i class="bi bi-link-45deg"></i> Copy Link</button>';
  if($p['review']) echo '<button class="btn btn-success js-review" data-decision="approve" data-need="0" data-title="Approve this document">Approve</button><button class="btn btn-warning text-dark js-review" data-decision="late_approve" data-need="0" data-title="Approve as Delayed/Late Submitted"><i class="bi bi-clock-history"></i> Approve as Delayed/Late</button><button class="btn btn-info js-review" data-decision="revise" data-need="1" data-title="Request revision">Request Revision</button><button class="btn btn-danger js-review" data-decision="reject" data-need="1" data-title="Reject this document">Reject</button>';
  if(($u['role']==='Faculty'||$u['role']==='Admin')&&empty($d['is_late'])&&$d['uploaded_by']!=$u['id']) echo post_btn('mark_late',$id,'<i class="bi bi-alarm-fill"></i> Mark as Delayed/Late','btn-outline-danger','Mark this student submission as Delayed / Late Submitted?');
  if($p['archive']) echo post_btn('archive',$id,'<i class="bi bi-archive"></i> Archive','btn-outline-dark','Archive this document? It leaves the active list but keeps its history and versions.');
  if($p['restore']) echo post_btn('restore',$id,'<i class="bi bi-arrow-counterclockwise"></i> Restore','btn-success','Restore this document to the active list?');
  if($p['delete']) echo post_btn('delete',$id,'<i class="bi bi-trash"></i> Delete Permanently','btn-danger','This permanently deletes the document, all versions and files. This cannot be undone.'); ?></div></div>
<div class="card border-0 shadow-sm mb-3"><div class="card-body flow"><?php foreach($steps as $i=>$s){ $c=$i<$cur?'done':($i===$cur?(in_array($st,['Rejected','Returned for Revision'])?'bad':'now'):''); echo "<span class='st $c'>".e($s)."</span>".($i<count($steps)-1?'<i class="bi bi-chevron-right text-muted small"></i>':''); } ?></div></div>
<div class="row g-3"><div class="col-lg-7">
 <div class="card border-0 shadow-sm mb-3"><div class="card-header bg-white"><strong>Document Details</strong></div><table class="table mb-0">
 <?php foreach([['Document ID',$d['document_id']],['Title',$d['title']],['Description',$d['description']?:'—'],['Document Type',$d['document_type']],['Category',$d['category_name']?:'—'],['Grade Level',$d['department_name']?:'—'],['Created / Uploaded By',$d['uploader']],['Submission Timing',(!empty($d['is_late'])||($d['submission_timing']??'')==='Delayed / Late Submitted')?'Delayed / Late Submitted (Received Past Cutoff)':'On Time'],['Date Received',$d['date_received']?date('M d, Y',strtotime($d['date_received'])):'—'],['Date Created / Uploaded',dt($d['created_at'])],['Approval Date',dt($d['approved_at'])],['Last Updated',dt($d['updated_at'])],['Access Level',$d['access_level']],['Tags',$d['tags']?:'—'],['File',$d['file_name'].' ('.strtoupper($d['file_type']).', '.number_format($d['file_size']/1024,1).' KB)'],['Current Version',$d['current_version']]] as [$k,$val]) echo '<tr><th class="w-25 text-muted fw-normal">'.e($k).'</th><td>'.nl2br(e($val)).'</td></tr>';
 if($d['archived_at']) echo '<tr><th class="text-muted fw-normal">Archived</th><td>'.dt($d['archived_at']).'</td></tr>'; ?></table></div>
 <div class="card border-0 shadow-sm"><div class="card-header bg-white"><strong>Version History</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Version</th><th>File</th><th>Uploaded By</th><th>Date</th><th></th></tr></thead><tbody>
 <?php foreach($vers as $x): ?><tr><td>v<?=e($x['version_number'])?><?=$x['version_number']===$d['current_version']?' <span class="badge bg-success">current</span>':''?></td><td><?=e($x['file_name'])?></td><td><?=e($x['full_name'])?></td><td class="small"><?=dt($x['created_at'])?></td><td><a class="btn btn-sm btn-outline-secondary" href="download.php?id=<?=$id?>&v=<?=$x['id']?>"><i class="bi bi-download"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<div class="col-lg-5">
 <div class="card border-0 shadow-sm mb-3"><div class="card-header bg-white"><strong>Review Trail</strong></div><ul class="list-group list-group-flush">
 <?php foreach($revs as $x): ?><li class="list-group-item small"><strong><?=e($x['action'])?></strong> by <?=e($x['full_name'])?><div class="text-muted"><?=dt($x['reviewed_at'])?></div><?php if($x['comments']) echo '<div class="mt-1">'.nl2br(e($x['comments'])).'</div>'; ?></li>
 <?php endforeach; if(!$revs) echo '<li class="list-group-item text-muted small">Not submitted for review yet.</li>'; ?></ul></div>
 <?php if($shares): ?><div class="card border-0 shadow-sm mb-3"><div class="card-header bg-white"><strong>Shared With</strong></div><ul class="list-group list-group-flush"><?php foreach($shares as $x): ?><li class="list-group-item small d-flex justify-content-between align-items-center"><span><?=e($x['full_name'])?> <span class="text-muted">(<?=e($x['role'])?>)</span><br><span class="text-muted">by <?=e($x['by_name'])?>, <?=dt($x['created_at'])?></span></span><?=post_btn('unshare',$id,'Remove','btn-outline-danger','Remove this person\'s access?','<input type="hidden" name="sid" value="'.$x['id'].'">')?></li><?php endforeach; ?></ul></div><?php endif; ?>
 <div class="card border-0 shadow-sm"><div class="card-header bg-white"><strong>Document History</strong></div><ul class="list-group list-group-flush" style="max-height:340px;overflow:auto">
 <?php foreach($hist as $x): ?><li class="list-group-item small"><strong><?=e($x['action'])?></strong> &middot; <?=e($x['full_name']??'system')?><div class="text-muted"><?=e($x['description'])?><br><?=dt($x['created_at'])?></div></li><?php endforeach; if(!$hist) echo '<li class="list-group-item text-muted small">No history yet.</li>'; ?></ul></div></div></div>
<?php if($p['review']): ?><form id="reviewForm" method="post" action="actions.php"><?=csrf_field()?><input type="hidden" name="act" value="review"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="decision" id="rvDecision"><input type="hidden" name="comments" id="rvComments"></form><?php endif; ?>
<?php if($p['share']): ?><div class="modal fade" id="shareM" tabindex="-1"><div class="modal-dialog"><form method="post" action="actions.php" class="modal-content"><?=csrf_field()?><input type="hidden" name="act" value="share"><input type="hidden" name="id" value="<?=$id?>">
 <div class="modal-header"><h5 class="modal-title">Share document</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
 <div class="modal-body"><label class="form-label">Send to (hold Ctrl/Cmd to select several)</label><select name="to[]" class="form-select" multiple size="8" required><?php foreach($targets as $x) echo '<option value="'.$x['id'].'">'.e($x['full_name']).' ('.e($x['role']).')</option>'; ?></select>
 <div class="form-text">The people you choose will be able to view and download this document. They will be notified.</div></div>
 <div class="modal-footer"><button class="btn btn-primary">Share</button></div></form></div></div><?php endif; ?>
<?php include 'includes/footer.php'; ?>
